            if (a[0] == b[0] && a[1] == b[1]) return (a[2] < b[2]);
            if (a[0] == b[0]) return (a[1] < b[1]);
            return (a[0] < b[0]);
        }
    };

    static bool isDegeneratedTriangle(const CGALTriangle &t);

